insert into stock_market_index_info ( id, market_code, cur_time, market_name, pre_close_point, open_point, cur_point, min_point, max_point, trade_amount, trade_volume ) VALUES
( #{smi.id,jdbcType=BIGINT}, #{smi.marketCode,jdbcType=CHAR}, #{smi.curTime,jdbcType=TIMESTAMP}, #{smi.marketName,jdbcType=VARCHAR}, #{smi.preClosePoint,jdbcType=DECIMAL}, #{smi.openPoint,jdbcType=DECIMAL}, #{smi.curPoint,jdbcType=DECIMAL}, #{smi.minPoint,jdbcType=DECIMAL}, #{smi.maxPoint,jdbcType=DECIMAL}, #{smi.tradeAmount,jdbcType=BIGINT},#{smi.tradeVolume,jdbcType=BIGINT} )
# 如果插入的数据已经存在，使用这段代码防止mysql报重复entry的错误。改代码的意思是如果重复则更新这些值而不是插入 ON DUPLICATE KEY UPDATE pre_close_point = VALUES(pre_close_point), open_point = VALUES(open_point), cur_point = VALUES(cur_point), min_point = VALUES(min_point), max_point = VALUES(max_point), trade_amount = VALUES(trade_amount), trade_volume = VALUES(trade_volume);
